pragma solidity 0.8.20;

import { AccessControlUpgradeable } from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import { ERC721Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import { ERC721EnumerableUpgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC721/extensions/ERC721EnumerableUpgradeable.sol";
import { ERC721PausableUpgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC721/extensions/ERC721PausableUpgradeable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { UUPSUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import { IERC165 } from "@openzeppelin/contracts/interfaces/IERC165.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Strings } from "@openzeppelin/contracts/utils/Strings.sol";
import { IStargateNFT } from "../interfaces/IStargateNFT.sol";
import { ITokenAuction } from "../interfaces/ITokenAuction.sol";
import { IStargateDelegation } from "../deprecated/StargateDelegation/V3/IStargateDelegation.sol";
import { DataTypes } from "./libraries/DataTypes.sol";
import { MintingLogic } from "./libraries/MintingLogic.sol";
import { Token } from "./libraries/Token.sol";
import { Clock } from "./libraries/Clock.sol";
import { Settings } from "./libraries/Settings.sol";
import { Errors } from "./libraries/Errors.sol";
import { Levels } from "./libraries/Levels.sol";
import { TokenManager } from "./libraries/TokenManager.sol";
import { IStargate } from "../interfaces/IStargate.sol";
import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

/// @title StargateNFT
/// @notice This contract is used to mint NFTs representing the staking position of the owner in the VeChain protocol,
/// and minting and burning is callable only by the Stargate contract. It is a continuation of the legacy TokenAuction (X-Node and Eco Nodes) collection,
/// and owners of the legacy NFTs can migrate their nodes and replace them with StargateNFTs.
/// StargateNFT contract is upgradable, and was originally deployed to handle the staking, unstaking and migration directly, but
/// with the deployment of the Stargate contract and the release of Hayabusa, this contract was upgraded to V3, transferring the responsibility
/// of staking, unstaking and migration to the Stargate contract.
///
/// This contract handles the maturity period of an NFT, which means that the NFT cannot be used to delegate to a validator until the maturity period ends.
/// Every NFT level has a different maturity period, and the maturity period is set when the NFT is minted. Migrated NFTs have no maturity period.
/// Users can decide to skip the maturity period by calling the boost function and paying a fee (VTHO).
///
/// The key differences between the legacy Nodes contract and the Stargate NFT collection are:
/// 01. Users hard stake their VET in the contract instead of soft staking in the wallet
/// 02. There is no possibility to upgrade/downgrade NFTs, once the NFT is minted it will always stay in the same level
/// 03. A user (or contract) can hold multiple NFTs, each with a different level
/// Conditions for migrating nodes:
/// 01. Own a node which is not maturing or on auction, +4h since last transfer, hold/send VET to the contract
/// 02. Migrated nodes will have no maturity period and the node on the legacy contract will be destroyed
/// Some other peculiarities of the Stargate NFT collection are:
/// 01. Users must deposit the exact amount of VET required to mint an NFT of a certain level, no more, no less
/// 02. The NFTs have a maturity period, after which they can start generate rewards by delegating to a validator - see Stargate contract
/// 03. All NFT levels have a cap, we are adding 3 new levels at launch, and more levels can be added in the future
///
/// In version 1 and 2 this contract was also storing the VET amount staked by the owners, and since before Hayabusa just holding VET was enough to generate VTHO,
/// this contract was also allowing owners to claim those base VTHO rewards.
/// Since with the release of Hayabusa VTHO is not generated anymore by holding VET, all functionalities related to VTHO were removed from this contract.
/// @dev This contract is UUPS upgradable and AccessControl protected.
///
/// ===================== VERSION 2 ===================== //
/// Some users incorrectly migrated their nodes and we added a functionality to allow those users to recover those tokens.
///
/// Storage changes:
/// - Added a new whitelistEntries mapping to the StargateNFTStorage
///
/// Other changes:
/// - New initializeV2 function to the StargateNFT contract, for initializing the whitelist entries
/// - New WHITELISTER_ROLE, for adding and removing whitelist entries
/// - New getWhitelistEntry function, for getting a whitelist entry
/// - Settings library: New addWhitelistEntry function, for adding (and updating) a whitelist entry
/// - Settings library: New removeWhitelistEntry function, for removing a whitelist entry
/// - MintingLogic library: New internal function _migrateFromWhitelist, called by migrate and migrateAndDelegate,
/// for migrating a token if it's on the whitelist
///
/// ===================== VERSION 3 ===================== //
/// The version 3 of this contract represents the release of Hayabusa, together with the release of the Stargate contract that acts as an entry point
/// for all interactions with the protocol and with minting and burning the NFTs.
///
/// Storage changes:
/// - Marked vthoToken, stargateDelegation, vthoGenerationEndTimestamp as deprecated storage values that won't be set/used from V3
///
/// Other changes:
/// - Removed everything related to vet generated vtho (setters, getters, library), since VTHO generation is now handled by the Stargate contract; (left only some getters for debugging purposes)
/// - Removed getters to optimize contract size: normalTokensCount, addWhitelistEntry, removeWhitelistEntry, setStargateDelegation, setLegacyNodes, stargateDelegation, getCap, canTransfer,
///   ownsNormalToken, isNormalToken, levelsOwnedBy
/// - Removed setters to optimize contract size: setStargateDelegation, setLegacyNodes, updateLevelCap, updateLevel
/// - NFT is now always transferable, even when it is delegated to a validator
/// - Claimable delegation rewards are not automatically claimed anymore upon a token transfer, only during unstake, and such action is handled by the Stargate contract
/// - Removed the migrate function, since we want to enforce entering the delegation
/// - Moved the following functions to the Stargate contract:
///   - stake
///   - unstake
///   - stakeAndDelegate
///   - migrateAndDelegate
/// - Added a new mint and burn methods, accessible only by the Stargate contract
/// - Added a boost feature that allows users to skip the maturity period by paying a fee (VTHO)
/// - Added a helper function to transfer the VET stored in this contract to the new Stargate contract
/// - Added the possibility for an owner to add a manager to his NFT; The access level of the managers are handled in the Stargate contract.
///   Upon a transfer, the manager is removed from the token.
/// - Added a function to migrate the manager of a token to the StargateNFT contract, this function is only callable by the TOKEN_MANAGER_MIGRATOR_ROLE
/// so we can migrate the storage from NodeManagementV3 to StargateNFT, after the migration we can remove this function
contract StargateNFT is
    AccessControlUpgradeable,
    ERC721Upgradeable,
    ERC721EnumerableUpgradeable,
    ERC721PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable,
    IStargateNFT
{
    using EnumerableSet for EnumerableSet.UintSet;

    uint256 public constant REWARD_MULTIPLIER_SCALING_FACTOR = 100;
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant LEVEL_OPERATOR_ROLE = keccak256("LEVEL_OPERATOR_ROLE");
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");
    bytes32 public constant TOKEN_MANAGER_MIGRATOR_ROLE = keccak256("TOKEN_MANAGER_MIGRATOR_ROLE");

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // ---------- Storage ---------- //

    // keccak256(abi.encode(uint256(keccak256("storage.StargateNFT")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant StargateNFTStorageLocation =
        0xec49bc12bd9c2cfd865ff38825256c053d253acea1262d51e4c4821cc4d5b700;

    function _getStargateNFTStorage()
        private
        pure
        returns (DataTypes.StargateNFTStorage storage $)
    {
        assembly {
            $.slot := StargateNFTStorageLocation
        }
    }

    /// @notice Returns the version of the contract, manually updated with each upgrade
    /// @return version - the version of the contract
    function version() public pure returns (uint256) {
        return 3;
    }

    /// @notice Initializes the contract
    function initialize(DataTypes.StargateNFTInitParams memory _initParams) external initializer {
        // Validate the input addresses are not zero

        if (
            _initParams.admin == address(0) ||
            _initParams.upgrader == address(0) ||
            _initParams.pauser == address(0) ||
            _initParams.levelOperator == address(0) ||
            _initParams.legacyNodes == address(0) ||
            _initParams.vthoToken == address(0) ||
            _initParams.stargateDelegation == address(0)
        ) {
            revert Errors.AddressCannotBeZero();
        }

        // Validate string parameters are not empty
        if (
            bytes(_initParams.tokenCollectionName).length == 0 ||
            bytes(_initParams.tokenCollectionSymbol).length == 0 ||
            bytes(_initParams.baseTokenURI).length == 0
        ) {
            revert Errors.StringCannotBeEmpty();
        }

        // Validate legacy last token ID is greater than 0
        if (_initParams.legacyLastTokenId == 0) {
            revert Errors.ValueCannotBeZero();
        }

        // Validate list of token levels is not empty
        if (_initParams.levelsAndSupplies.length == 0) {
            revert Errors.ArrayCannotHaveZeroLength();
        }

        // Initialize the contract
        __ERC721_init(_initParams.tokenCollectionName, _initParams.tokenCollectionSymbol);
        __ERC721Enumerable_init();
        __ERC721Pausable_init();
        __ReentrancyGuard_init();
        __AccessControl_init();
        __UUPSUpgradeable_init();

        // Grant roles to the admin, upgrader, pauser, and level operator
        _grantRole(DEFAULT_ADMIN_ROLE, _initParams.admin);
        _grantRole(UPGRADER_ROLE, _initParams.upgrader);
        _grantRole(PAUSER_ROLE, _initParams.pauser);
        _grantRole(LEVEL_OPERATOR_ROLE, _initParams.levelOperator);

        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();

        // Add provided token levels
        for (uint256 i; i < _initParams.levelsAndSupplies.length; i++) {
            Levels.addLevel($, _initParams.levelsAndSupplies[i]);
        }

        // Initialize the storage
        $.legacyNodes = ITokenAuction(_initParams.legacyNodes);
        $.stargateDelegation_deprecated = IStargateDelegation(_initParams.stargateDelegation);
        $.vthoToken = IERC20(_initParams.vthoToken);
        $.currentTokenId = _initParams.legacyLastTokenId;
        $.baseTokenURI = _initParams.baseTokenURI;
    }

    /// @notice Initializes the contract v2
    /// @dev Not doing anything here, since in V3 we removed the logic for whitelist entries
    function initializeV2(
        DataTypes.WhitelistEntryInit[] memory _whitelistEntries
    ) external onlyRole(UPGRADER_ROLE) reinitializer(2) {
        // Do nothing
    }

    function initializeV3(
        address stargate,
        uint8[] memory levelIds,
        uint256[] memory boostPricesPerBlock
    ) external onlyRole(UPGRADER_ROLE) reinitializer(3) {
        if (stargate == address(0)) {
            revert Errors.AddressCannotBeZero();
        }

        if (levelIds.length != boostPricesPerBlock.length) {
            revert Errors.ArraysLengthMismatch();
        }

        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        $.stargate = IStargate(stargate);
        for (uint256 i; i < levelIds.length; i++) {
            Levels.updateLevelBoostPricePerBlock($, levelIds[i], boostPricesPerBlock[i]);
        }
    }

    // ---------- Modifiers ---------- //

    /// @notice Modifier to restrict access to only the Hayabusa Stargate contract
    /// @dev Only the Hayabusa Stargate contract can call this function
    modifier onlyStargate() {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        if (msg.sender != address($.stargate)) {
            revert Errors.UnauthorizedCaller(msg.sender);
        }
        _;
    }

    // ---------- Authorizers ---------- //

    /// @notice Authorizes the upgrade of the contract
    /// @param newImplementation - the new implementation address
    function _authorizeUpgrade(
        address newImplementation
    ) internal virtual override onlyRole(UPGRADER_ROLE) {}

    // ---------- Callbacks ---------- //

    /// @inheritdoc IStargateNFT
    function _safeMintCallback(address to, uint256 tokenId) external {
        // Validate caller is this contract
        if (msg.sender != address(this)) {
            revert Errors.UnauthorizedCaller(msg.sender);
        }

        _safeMint(to, tokenId);
    }

    /// @inheritdoc IStargateNFT
    function _burnCallback(uint256 tokenId) external {
        // Validate caller is this contract
        if (msg.sender != address(this)) {
            revert Errors.UnauthorizedCaller(msg.sender);
        }
        _burn(tokenId);
    }

    // ---------- Pausing Functions ---------- //

    /// @inheritdoc IStargateNFT
    function pause() public onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /// @inheritdoc IStargateNFT
    function unpause() public onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // ---------- Level Functions ---------- //

    /// @inheritdoc IStargateNFT
    function addLevel(
        DataTypes.LevelAndSupply memory _levelAndSupply,
        uint256 _boostPricePerBlock
    ) public onlyRole(LEVEL_OPERATOR_ROLE) {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        Levels.addLevel($, _levelAndSupply);
        Levels.updateLevelBoostPricePerBlock($, $.MAX_LEVEL_ID, _boostPricePerBlock);
    }

    /// @inheritdoc IStargateNFT
    function getLevelIds() external view returns (uint8[] memory) {
        return Levels.getLevelIds(_getStargateNFTStorage());
    }

    /// @inheritdoc IStargateNFT
    function getLevel(uint8 _levelId) external view returns (DataTypes.Level memory) {
        return Levels.getLevel(_getStargateNFTStorage(), _levelId);
    }

    /// @inheritdoc IStargateNFT
    function getLevels() external view returns (DataTypes.Level[] memory) {
        return Levels.getLevels(_getStargateNFTStorage());
    }

    /// @inheritdoc IStargateNFT
    function getLevelsCirculatingSupplies() external view returns (uint208[] memory) {
        return Levels.getLevelsCirculatingSupplies(_getStargateNFTStorage());
    }

    /// @inheritdoc IStargateNFT
    function getLevelSupply(uint8 _levelId) public view returns (uint208 circulating, uint32 cap) {
        (circulating, cap) = Levels.getLevelSupply(_getStargateNFTStorage(), _levelId);
    }

    /// @inheritdoc IStargateNFT
    function getCirculatingSupplyAtBlock(
        uint8 _levelId,
        uint48 _blockNumber
    ) external view returns (uint208) {
        return Levels.getCirculatingSupplyAtBlock(_getStargateNFTStorage(), _levelId, _blockNumber);
    }

    /// @inheritdoc IStargateNFT
    function getLevelsCirculatingSuppliesAtBlock(
        uint48 _blockNumber
    ) external view returns (uint208[] memory) {
        return Levels.getLevelsCirculatingSuppliesAtBlock(_getStargateNFTStorage(), _blockNumber);
    }

    // ---------- Token Functions ---------- //

    /// @inheritdoc IStargateNFT
    function getCurrentTokenId() external view returns (uint256) {
        return _getStargateNFTStorage().currentTokenId;
    }

    /// @inheritdoc IStargateNFT
    function getToken(uint256 _tokenId) public view returns (DataTypes.Token memory) {
        return Token.getToken(_getStargateNFTStorage(), _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function getTokenLevel(uint256 _tokenId) external view returns (uint8) {
        return _getStargateNFTStorage().tokens[_tokenId].levelId;
    }

    /// @inheritdoc IStargateNFT
    function tokensOwnedBy(address _owner) external view returns (DataTypes.Token[] memory) {
        return Token.tokensOwnedBy(_getStargateNFTStorage(), _owner);
    }

    /// @inheritdoc IStargateNFT
    function ownerTotalVetStaked(address _owner) external view returns (uint256) {
        return Token.ownerTotalVetStaked(_getStargateNFTStorage(), _owner);
    }

    /// @inheritdoc IStargateNFT
    function idsOwnedBy(address _owner) public view returns (uint256[] memory) {
        return Token.idsOwnedBy(_owner);
    }

    /// @inheritdoc IStargateNFT
    function tokenExists(uint256 _tokenId) external view returns (bool) {
        address owner = _ownerOf(_tokenId);
        if (owner == address(0)) {
            return false;
        }

        return true;
    }

    // ---------- Boosting Functions ---------- //

    /// @inheritdoc IStargateNFT
    function boost(uint256 _tokenId) external nonReentrant whenNotPaused {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        MintingLogic.boostOnBehalfOf($, msg.sender, _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function boostAmount(uint256 _tokenId) external view returns (uint256) {
        return MintingLogic.boostAmount(_getStargateNFTStorage(), _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function boostAmountOfLevel(uint8 _levelId) external view returns (uint256) {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        return $.boostPricePerBlock[_levelId] * $.levels[_levelId].maturityBlocks;
    }

    /// @inheritdoc IStargateNFT
    function boostPricePerBlock(uint8 _levelId) external view returns (uint256) {
        return _getStargateNFTStorage().boostPricePerBlock[_levelId];
    }

    /// @inheritdoc IStargateNFT
    function maturityPeriodEndBlock(uint256 _tokenId) external view returns (uint64) {
        return Token.maturityPeriodEndBlock(_getStargateNFTStorage(), _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function isUnderMaturityPeriod(uint256 _tokenId) external view returns (bool) {
        return Token.isUnderMaturityPeriod(_getStargateNFTStorage(), _tokenId);
    }

    // ---------- Token Manager Functions ---------- //

    /// @inheritdoc IStargateNFT
    function addTokenManager(address _manager, uint256 _tokenId) external {
        TokenManager.addTokenManager(_getStargateNFTStorage(), _manager, _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function removeTokenManager(uint256 _tokenId) external {
        TokenManager.removeTokenManager(_getStargateNFTStorage(), _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function getTokenManager(uint256 _tokenId) external view returns (address) {
        return TokenManager.getTokenManager(_getStargateNFTStorage(), _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function idsManagedBy(address _user) external view returns (uint256[] memory) {
        return TokenManager.idsManagedBy(_getStargateNFTStorage(), _user);
    }

    /// @inheritdoc IStargateNFT
    function tokensManagedBy(address _user) external view returns (DataTypes.Token[] memory) {
        return TokenManager.tokensManagedBy(_getStargateNFTStorage(), _user);
    }

    /// @inheritdoc IStargateNFT
    function isTokenManager(address _manager, uint256 _tokenId) external view returns (bool) {
        return TokenManager.isTokenManager(_getStargateNFTStorage(), _manager, _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function isManagedByOwner(uint256 _tokenId) external view returns (bool) {
        return TokenManager.isManagedByOwner(_getStargateNFTStorage(), _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function tokensOverview(
        address _user
    ) external view returns (DataTypes.TokenOverview[] memory) {
        return TokenManager.tokensOverview(_getStargateNFTStorage(), _user);
    }

    // ---------- Base URI Functions ---------- //

    /// @inheritdoc IStargateNFT
    function setBaseURI(string memory _baseTokenURI) external onlyRole(MANAGER_ROLE) {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        Settings.setBaseURI($, _baseTokenURI);
    }

    /// @inheritdoc IStargateNFT
    function baseURI() external view returns (string memory) {
        return _baseURI();
    }

    // ---------- Stargate functions ---------- //

    /// @inheritdoc IStargateNFT
    function mint(
        uint8 _levelId,
        address _to
    ) external onlyStargate nonReentrant whenNotPaused returns (uint256 tokenId) {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        return MintingLogic.mint($, _levelId, _to);
    }

    /// @inheritdoc IStargateNFT
    function burn(uint256 _tokenId) external onlyStargate nonReentrant whenNotPaused {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        MintingLogic.burn($, _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function migrate(uint256 _tokenId) external onlyStargate nonReentrant whenNotPaused {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        MintingLogic.migrate($, _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function boostOnBehalfOf(
        address _sender,
        uint256 _tokenId
    ) external onlyStargate nonReentrant whenNotPaused {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        MintingLogic.boostOnBehalfOf($, _sender, _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function getStargate() external view returns (address) {
        return address(_getStargateNFTStorage().stargate);
    }

    // ---------- Clock Functions ---------- //

    /// @inheritdoc IStargateNFT
    function clock() public view returns (uint48) {
        return Clock.clock();
    }

    /// @inheritdoc IStargateNFT
    function CLOCK_MODE() public pure returns (string memory) {
        return Clock.CLOCK_MODE();
    }

    /// @inheritdoc IStargateNFT
    function timestamp() public view returns (uint48) {
        return Clock.timestamp();
    }

    // ---------- VTHO Functions ---------- //

    /// @inheritdoc IStargateNFT
    function getVthoTokenAddress() external view returns (address) {
        return address(_getStargateNFTStorage().vthoToken);
    }

    // ---------- Legacy Nodes Functions ---------- //

    /// @inheritdoc IStargateNFT
    function xTokensCount() external view returns (uint208) {
        return Token.xTokensCount(_getStargateNFTStorage());
    }

    /// @inheritdoc IStargateNFT
    function ownsXToken(address _owner) external view returns (bool) {
        return Token.ownsXToken(_getStargateNFTStorage(), _owner);
    }

    /// @inheritdoc IStargateNFT
    function isXToken(uint256 _tokenId) external view returns (bool) {
        return Token.isXToken(_getStargateNFTStorage(), _tokenId);
    }

    /// @inheritdoc IStargateNFT
    function legacyNodes() external view returns (ITokenAuction) {
        return _getStargateNFTStorage().legacyNodes;
    }

    // ---------- Override Functions ---------- //

    /// @notice Public override of the ERC721Upgradeable.tokenURI function
    /// @param _tokenId - the token ID to get the token URI for
    /// @return tokenURI - the token URI string if the token exists, revert otherwise
    function tokenURI(
        uint256 _tokenId
    ) public view override(ERC721Upgradeable) returns (string memory) {
        // check if the token exists
        _requireOwned(_tokenId);

        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();

        // Get token level ID
        uint8 levelId = $.tokens[_tokenId].levelId;

        return Token.tokenURI($, _tokenId, Strings.toString(levelId));
    }

    /// @notice Public override of the supportsInterface function
    /// @param _interfaceId The interface ID to check
    /// @return true if the contract implements the interface, false otherwise
    function supportsInterface(
        bytes4 _interfaceId
    )
        public
        view
        override(ERC721Upgradeable, ERC721EnumerableUpgradeable, AccessControlUpgradeable, IERC165)
        returns (bool)
    {
        return super.supportsInterface(_interfaceId);
    }

    // ---------- Internal Functions ---------- //

    /// @notice Internal override of the _update function
    /// @param _to - the new owner of the NFT
    /// @param _tokenId - the token ID of the NFT
    /// @param _auth - the address that is authorizing the transfer
    /// @return the address of the new owner
    function _update(
        address _to,
        uint256 _tokenId,
        address _auth
    )
        internal
        override(ERC721Upgradeable, ERC721EnumerableUpgradeable, ERC721PausableUpgradeable)
        returns (address)
    {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();

        address manager = $.tokenIdToManager[_tokenId];

        // Remove the manager from the token
        if (manager != address(0)) {
            delete $.tokenIdToManager[_tokenId];
            $.managerToTokenIds[manager].remove(_tokenId);

            emit TokenManagerRemoved(_tokenId, manager);
        }

        return super._update(_to, _tokenId, _auth);
    }

    /// @notice Internal override of the _increaseBalance function
    /// @param account - the address to increase the balance for
    /// @param value - the amount to increase the balance by
    function _increaseBalance(
        address account,
        uint128 value
    ) internal override(ERC721Upgradeable, ERC721EnumerableUpgradeable) {
        super._increaseBalance(account, value);
    }

    /// @notice Internal override of the ERC721Upgradeable._baseURI function
    /// @return baseURI - the base URI string
    function _baseURI() internal view override(ERC721Upgradeable) returns (string memory) {
        return _getStargateNFTStorage().baseTokenURI;
    }

    // ---------- Temporary Functions ---------- //

    /// @inheritdoc IStargateNFT
    function transferBalance(uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        uint256 balance = address(this).balance;
        if (amount > balance) {
            revert Errors.InsufficientContractBalance(balance, amount);
        }
        (bool success, ) = payable(address($.stargate)).call{ value: amount }("");
        if (!success) {
            revert Errors.VetTransferFailed(address($.stargate), amount);
        }
    }

    /// @inheritdoc IStargateNFT
    function migrateTokenManager(
        uint256 _tokenId,
        address _manager
    ) external onlyRole(TOKEN_MANAGER_MIGRATOR_ROLE) {
        DataTypes.StargateNFTStorage storage $ = _getStargateNFTStorage();
        TokenManager.migrateTokenManager($, _tokenId, _manager);
    }
}

contracts/interfaces/IStargateNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import { IERC721 } from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import { IERC721Enumerable } from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Enumerable.sol";
import { IERC165 } from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import { DataTypes } from "../StargateNFT/libraries/DataTypes.sol";
import { ITokenAuction } from "./ITokenAuction.sol";

interface IStargateNFT is IERC165, IERC721, IERC721Enumerable {
    // ------------------ Events ------------------ //

    /**
     * @notice Emitted when a token level is updated
     * @param levelId The ID of the level that was updated
     * @param name The new name of the level
     * @param isX The new X status
     * @param maturityBlocks The new maturity period in blocks
     * @param scaledRewardFactor The new scaled reward multiplier
     * @param vetAmountRequiredToStake The new VET amount required for staking
     */
    event LevelUpdated(
        uint8 indexed levelId,
        string name,
        bool isX,
        uint64 maturityBlocks,
        uint64 scaledRewardFactor,
        uint256 vetAmountRequiredToStake
    );

    /**
     * @notice Emitted when the circulating supply of a token level is updated
     * @param levelId The ID of the level supply that was updated
     * @param oldCirculatingSupply The old circulating supply
     * @param newCirculatingSupply The new circulating supply
     */
    event LevelCirculatingSupplyUpdated(
        uint8 indexed levelId,
        uint208 oldCirculatingSupply,
        uint208 newCirculatingSupply
    );

    /**
     * @notice Emitted when the cap of a token level is updated
     * @param levelId The ID of the level cap that was updated
     * @param oldCap The old cap
     * @param newCap The new cap
     */
    event LevelCapUpdated(uint8 indexed levelId, uint32 oldCap, uint32 newCap);

    /**
     * @notice Emitted when the boost price per block of a token level is updated
     * @param levelId The ID of the level boost price per block that was updated
     * @param oldBoostPricePerBlock The old boost price per block
     * @param newBoostPricePerBlock The new boost price per block
     */
    event LevelBoostPricePerBlockUpdated(
        uint8 indexed levelId,
        uint256 oldBoostPricePerBlock,
        uint256 newBoostPricePerBlock
    );

    /**
     * @notice Emitted when an NFT is minted
     * @param owner The address that owns the newly minted NFT
     * @param levelId The level ID of the newly minted NFT
     * @param migrated Whether the token was migrated from legacy nodes contract
     * @param tokenId The ID of the newly minted NFT
     * @param vetAmountStaked The amount of VET staked to mint the NFT
     */
    event TokenMinted(
        address indexed owner,
        uint8 indexed levelId,
        bool indexed migrated,
        uint256 tokenId,
        uint256 vetAmountStaked
    );

    /**
     * @notice Emitted when an NFT is burned
     * @param owner The address that owns the newly burned NFT
     * @param levelId The level ID of the newly burned NFT
     * @param tokenId The ID of the newly burned NFT
     * @param vetAmountStaked The amount of VET staked to burn the NFT
     */
    event TokenBurned(
        address indexed owner,
        uint8 indexed levelId,
        uint256 tokenId,
        uint256 vetAmountStaked
    );

    /**
     * @notice Emitted when the base URI for the token metadata is updated
     * @param oldBaseURI The old base URI
     * @param newBaseURI The new base URI
     */
    event BaseURIUpdated(string oldBaseURI, string newBaseURI);

    /**
     * @notice Emitted when a token manager is added to a token
     * @param tokenId The ID of the token
     * @param manager The address of the manager
     */
    event TokenManagerAdded(uint256 indexed tokenId, address indexed manager);

    /**
     * @notice Emitted when a token manager is removed from a token
     * @param tokenId The ID of the token
     * @param manager The address of the manager
     */
    event TokenManagerRemoved(uint256 indexed tokenId, address indexed manager);

    /** ------------------ Deprecated Events ------------------ */
    // These events are deprecated in V3 but we
    // keep them for backwards compatibility and
    // for indexing purposes

    /**
     * @notice Emitted when VTHO rewards are claimed for a token
     * @dev Not emitted anymore in V3, since we don't generate VTHO anymore
     * @param owner The address that claimed the rewards
     * @param tokenId The ID of the token for which rewards were claimed
     * @param amount The amount of VTHO rewards claimed
     * @dev Deprecated in V3
     */
    event BaseVTHORewardsClaimed(address indexed owner, uint256 indexed tokenId, uint256 amount);

    /**
     * @notice Emitted when the VTHO generation end timestamp is updated
     * @dev Not emitted anymore in V3, since there is no need to set this value anymore
     * @param oldVthoGenerationEndTimestamp The old VTHO generation end timestamp
     * @param newVthoGenerationEndTimestamp The new VTHO generation end timestamp
     */
    event VthoGenerationEndTimestampSet(
        uint48 oldVthoGenerationEndTimestamp,
        uint48 newVthoGenerationEndTimestamp
    );

    // ------------------ Constants ------------------ //

    /// @notice Returns the reward multiplier scaling factor
    /// @return REWARD_MULTIPLIER_SCALING_FACTOR - the reward multiplier scaling factor
    function REWARD_MULTIPLIER_SCALING_FACTOR() external view returns (uint256);

    // ------------------ Functions ------------------ //

    function version() external view returns (uint256);

    /*------- Callbacks -------*/

    /// @notice Callback function to ERC721Upgradeable._safeMint, called by StargateNFTMinting.stake
    /// @dev Only the StargateNFT contract can call this function
    /// @param to - the address to mint the token to
    /// @param tokenId - the token ID of the token to mint
    function _safeMintCallback(address to, uint256 tokenId) external;

    /// @notice Callback function to ERC721Upgradeable._burn, called by StargateNFTMinting.unstake
    /// @dev Only the StargateNFT contract can call this function
    /// @param tokenId - the token ID of the token to burn
    function _burnCallback(uint256 tokenId) external;

    /*------- Pausing Functions -------*/

    /// @notice Pauses the StargateNFT contract
    /// @dev Only the PAUSER_ROLE can call this function
    /// @dev Pausing the contract will prevent minting
    function pause() external;

    /// @notice Unpauses the StargateNFT contract
    /// @dev Only the PAUSER_ROLE can call this function
    function unpause() external;

    /*------- Level Functions -------*/

    /// @notice Adds a new token level
    /// @param _levelAndSupply - The level and supply to add, see {DataTypes.LevelAndSupply}
    /// @param _boostPricePerBlock - The boost price per block for the level
    /// @dev Only the LEVEL_OPERATOR_ROLE can call this function
    /// Check the {Levels.addLevel} library function for more details
    /// Emits a {IStargateNFT.LevelUpdated} event
    /// Emits a {IStargateNFT.LevelCirculatingSupplyUpdated} event
    /// Emits a {IStargateNFT.LevelCapUpdated} event
    /// Emits a {IStargateNFT.LevelBoostPricePerBlockUpdated} event
    function addLevel(
        DataTypes.LevelAndSupply memory _levelAndSupply,
        uint256 _boostPricePerBlock
    ) external;

    /// @notice Returns a list of all token level spec IDs
    /// @return levelIds - The list of token level spec IDs
    function getLevelIds() external view returns (uint8[] memory);

    /// @notice Returns a token level spec for a given level ID
    /// @param _levelId The ID of the token level spec to return
    /// @return Level - The token level spec
    function getLevel(uint8 _levelId) external view returns (DataTypes.Level memory);

    /// @notice Returns a list of all token level specs
    /// @return levels - The list of token level specs
    function getLevels() external view returns (DataTypes.Level[] memory);

    /// @notice Returns the circulating supply for all levels
    /// @return circulatingSupplies An array of circulating supply values for all levels, sorted by level id
    function getLevelsCirculatingSupplies() external view returns (uint208[] memory);

    /// @notice Returns the circulating supply and cap for a given token level
    /// @param _levelId The ID of the token level to get supply data for
    /// @return circulating The circulating supply of the token level
    /// @return cap The cap of the token level
    function getLevelSupply(uint8 _levelId) external view returns (uint208 circulating, uint32 cap);

    /// @notice Returns the circulating supply for a given level at a specific block
    /// @param _levelId The ID of the level to get supply data for
    /// @param _blockNumber The block number to get the supply at
    /// @return circulatingSupply The circulating supply of the level at the specified block
    function getCirculatingSupplyAtBlock(
        uint8 _levelId,
        uint48 _blockNumber
    ) external view returns (uint208);

    /// @notice Returns the circulating supply for all levels at a certain block
    /// @param _blockNumber The block number to get the supply at
    /// @return circulatingSupplies An array of circulating supply values for all levels, sorted by level id
    function getLevelsCirculatingSuppliesAtBlock(
        uint48 _blockNumber
    ) external view returns (uint208[] memory);

    // ---------- Token Functions ---------- //

    /// @notice Get the latest token id that was minted
    /// @dev Ids start from the total supply of the legacy contrat
    /// @return currentTokenId the latest token id that was minted
    function getCurrentTokenId() external view returns (uint256);

    /// @notice Returns a token for a given token ID
    /// @param _tokenId The ID of the token to get
    /// @return token The token
    function getToken(uint256 _tokenId) external view returns (DataTypes.Token memory);

    /// @notice Returns the level ID of a given token
    /// @param _tokenId - the token ID of the NFT
    /// @return levelId - the level ID of the NFT
    function getTokenLevel(uint256 _tokenId) external view returns (uint8);

    /// @notice Returns the tokens owned by an address
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the owner has a lot of tokens.
    /// @param _owner The address to get tokens for
    /// @return tokens An array of tokens owned by the address
    function tokensOwnedBy(address _owner) external view returns (DataTypes.Token[] memory);

    /// @notice Returns the total VET staked by an address
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the owner has a lot of tokens.
    /// @param _owner The address to get total VET staked for
    /// @return totalVetStaked The total VET staked by the address
    function ownerTotalVetStaked(address _owner) external view returns (uint256);

    /// @notice Returns a list of token IDs for a given owner
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the owner has a lot of tokens.
    /// @param _owner The address of the owner to get token IDs for
    /// @return tokenIds The list of token IDs
    function idsOwnedBy(address _owner) external view returns (uint256[] memory);

    /// @notice Returns true if a token exists
    /// @param _tokenId The ID of the token to check
    /// @return True if the token exists, false otherwise
    function tokenExists(uint256 _tokenId) external view returns (bool);

    // ---------- Boosting Functions ------------ //

    /// @notice Boosts the maturity period of a token
    /// @dev This can only be called by the Stargate contract
    /// @param _tokenId The ID of the token to boost
    /// @dev Emits a {IStargateNFT.MaturityPeriodBoosted} event
    function boost(uint256 _tokenId) external;

    /// @notice Returns the amount of VTHO required to boost a token's maturity period
    /// @param _tokenId The ID of the token to boost
    /// @return boostAmount The amount of VTHO required to boost the token's maturity period
    function boostAmount(uint256 _tokenId) external view returns (uint256);

    /// @notice Returns the amount of VTHO required to boost a token's maturity period
    /// @param _levelId The level ID of the token to boost
    /// @return boostAmount The amount of VTHO required to boost the token's maturity period
    function boostAmountOfLevel(uint8 _levelId) external view returns (uint256);

    /// @notice Returns the boost price per block for a given level
    /// @param _levelId The level ID of the token to boost
    /// @return boostPricePerBlock The boost price per block for the level
    function boostPricePerBlock(uint8 _levelId) external view returns (uint256);

    /// @notice Returns the maturity period end block for a given token
    /// @param _tokenId The ID of the token to get maturity period end block for
    /// @return maturityPeriodEndBlock The maturity period end block
    function maturityPeriodEndBlock(uint256 _tokenId) external view returns (uint64);

    /// @notice Returns true if a token is in the maturity period
    /// @param _tokenId The ID of the token to check
    /// @return isInMaturityPeriod True if the token is in the maturity period, false otherwise
    function isUnderMaturityPeriod(uint256 _tokenId) external view returns (bool);

    // ---------- Token Manager Functions ---------- //

    /// @notice Adds a manager to a token
    /// @dev This manager can use the token for voting on VeVote
    /// or in B3TR but it cant calim rewards for themselves, transfer,
    /// delegate or unstake the token
    /// @dev If a token already has a manager, it will be removed and
    /// the new manager will be added
    /// @param _manager The address of the manager to add
    /// @param _tokenId The ID of the token to add the manager to
    /// @dev Emits a {IStargateNFT.TokenManagerAdded} event
    function addTokenManager(address _manager, uint256 _tokenId) external;

    /// @notice Removes a manager from a token
    /// @dev This manager can no longer use the token for voting on VeVote
    /// or in B3TR but it can still claim rewards for themselves, transfer,
    /// delegate or unstake the token
    /// @dev If a token has no manager, it will revert
    /// @param _tokenId The ID of the token to remove the manager from
    /// @dev Emits a {IStargateNFT.TokenManagerRemoved} event
    function removeTokenManager(uint256 _tokenId) external;

    /// @notice Returns the manager of a token, if the token does not have a manager
    /// it will return the owner of the token
    /// @param _tokenId The ID of the token to get the manager for
    /// @return manager The manager of the token
    function getTokenManager(uint256 _tokenId) external view returns (address);

    /// @notice Returns the list of:
    /// 1) Token ids managed by the user
    /// 2) Token ids owned by the user and not managed by someone else
    /// Token ids owned by the user, but managed by others, won't be returned
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the user has a lot of tokens.
    /// @param _user The address of the user to get the tokens for
    /// @return tokenIds The list of token ids managed by the user
    function idsManagedBy(address _user) external view returns (uint256[] memory);

    /// @notice Returns the list of:
    /// 1) Tokens managed by the user
    /// 2) Tokens owned by the user and not managed by someone else
    /// Tokens owned by the user, but managed by others, won't be returned
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the user has a lot of tokens.
    /// @param _user The address of the user to get the tokens for
    /// @return tokens The list of tokens managed by the user
    function tokensManagedBy(address _user) external view returns (DataTypes.Token[] memory);

    /// @notice Checks if an address is a manager of a token
    /// @param _manager The address of the manager to check
    /// @param _tokenId The ID of the token to check
    /// @return True if the address is a manager of the token, false otherwise
    function isTokenManager(address _manager, uint256 _tokenId) external view returns (bool);

    /// @notice Checks if a token is managed by the owner
    /// @param _tokenId The ID of the token to check
    /// @return True if the token is managed by the owner, false otherwise
    function isManagedByOwner(uint256 _tokenId) external view returns (bool);

    /// @notice Function to get the overview of the tokens related to a user
    /// A token is related to a user if it is owned by the user or if it is managed by the user
    /// This includes:
    /// - Tokens owned by the user and managed by the user
    /// - Tokens owned by the user and not managed by the user
    /// - Tokens managed by the user and not owned by the user
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the user has a lot of tokens.
    /// @param _user The address of the user to get the overview of the tokens
    /// @return DataTypes.TokenOverview[] The overview of the tokens related to the user
    function tokensOverview(address _user) external view returns (DataTypes.TokenOverview[] memory);

    // ---------- Base URI Functions ---------- //

    /// @notice Sets the base URI for the token collection metadata
    /// @dev Only the MANAGER_ROLE can call this function
    /// @dev Metadata is hosted on IPFS, and the base URI is the base path to the collection metadata
    /// @param _baseTokenURI The new base URI
    /// @dev Emits a {IStargateNFT.BaseURIUpdated} event
    function setBaseURI(string memory _baseTokenURI) external;

    /// @notice Returns the base URI for the token collection metadata
    /// @return baseURI - the base URI string
    function baseURI() external view returns (string memory);

    // ---------- Stargate functions ---------- //

    /// @notice Mints a token from the StargateNFT contract
    /// @dev This can only be called by the Stargate contract
    /// @param _levelId The ID of the token level to mint
    /// @param _to The address to mint the token to
    /// @dev Emits a {IStargateNFT.TokenMinted} event
    function mint(uint8 _levelId, address _to) external returns (uint256 tokenId);

    /// @notice Burns a token from the StargateNFT contract
    /// @dev This can only be called by the Stargate contract
    /// @param _tokenId The ID of the token to burn
    /// @dev Emits a {IStargateNFT.TokenBurned} event
    function burn(uint256 _tokenId) external;

    /// @notice Migrates a token from the legacy nodes contract to StargateNFT to the same owner address
    /// as the owner of the token in the legacy nodes contract
    /// @dev This can only be called by the Stargate contract
    /// @param _tokenId The ID of the token to migrate
    /// @dev Emits a {IStargateNFT.TokenMinted} event and a {IStargateNFT.TokenMigrated} event
    function migrate(uint256 _tokenId) external;

    /// @notice Boosts the maturity period of a token
    /// @dev This can only be called by the Stargate contract
    /// @param _sender The address to boost the token for
    /// @param _tokenId The ID of the token to boost
    /// @dev Emits a {IStargateNFT.MaturityPeriodBoosted} event
    function boostOnBehalfOf(address _sender, uint256 _tokenId) external;

    /// @notice Returns the address of the Stargate contract
    /// @return stargate - the Stargate contract
    function getStargate() external view returns (address);

    // ---------- Clock Functions ---------- //

    /// @notice Returns the current block number
    /// @return blockNumber - the current block number
    function clock() external view returns (uint48);

    /// @notice Returns the clock mode
    function CLOCK_MODE() external view returns (string memory);

    /// @notice Returns the current timestamp
    /// @return timestamp - the current timestamp
    function timestamp() external view returns (uint48);

    // ---------- VTHO Functions ---------- //

    /// @notice Returns the address of the VTHO token contract
    /// @return vthoToken - the VTHO token contract
    function getVthoTokenAddress() external view returns (address);

    // ---------- Legacy Nodes Functions ---------- //

    /// @notice Returns the number of X tokens in circulation
    /// @dev Get the count of normal tokens by subtracting the count of X tokens from the total supply
    /// @return xTokensCount - the number of X tokens
    function xTokensCount() external view returns (uint208);

    /// @notice Checks if an owner owns an X token
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the owner has a lot of tokens.
    /// @param _owner The address of the owner to check
    /// @return True if the owner owns an X token, false otherwise
    function ownsXToken(address _owner) external view returns (bool);

    /// @notice Checks if a token is an X token
    /// @param _tokenId The ID of the token to check
    /// @return True if the token is an X token, false otherwise
    function isXToken(uint256 _tokenId) external view returns (bool);

    /// @notice Returns the legacy nodes contract
    /// @return legacyNodes - the legacy nodes contract
    function legacyNodes() external view returns (ITokenAuction);

    // ---------- Temporary Functions ---------- //

    /// @notice Transfers the balance of the contract to the Stargate contract
    /// @dev This function was created after the refactor on the StargateNFT and Stargate
    /// contracts. After the refactor, all VET is handled by Stargate, this means
    /// stake, stakeAndDelegate, unstake... functions were moved to the Stargate.
    /// Since up until now we were using the StagateNFT contract to handle the VET,
    /// we need to transfer back all the previous staked VET to the Stargate
    /// so user can delegate it and unstake it. This functions transfers all the VET
    /// to the Stargate contract in one go.
    /// This function is called by the admin after the upgrade to V3 and the
    /// Stargate variable is set to the correct value
    /// @dev Only the DEFAULT_ADMIN_ROLE can call this function
    /// @dev Reverts with {IStargateNFT.VetTransferFailed} if the transfer fails
    function transferBalance(uint256 amount) external;

    /// @notice Migrate a token manager to the StargateNFT contract, this function is only callable by the TOKEN_MANAGER_MIGRATOR_ROLE
    /// so we can migrate the storage from NodeManagementV3 to StargateNFT, after the migration we can remove this function
    /// @param _tokenId The ID of the token to migrate
    /// @param _manager The address of the manager to migrate
    function migrateTokenManager(uint256 _tokenId, address _manager) external;
}

contracts/interfaces/ITokenAuction.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

interface ITokenAuction {
    // ------------ Events ------------ //
    // TODO: revisit interface
    event AuctionCreated(
        uint256 indexed _auctionId,
        uint256 indexed _tokenId,
        uint256 _startingPrice,
        uint256 _endingPrice,
        uint64 _duration
    );

    event AuctionSuccessful(
        uint256 indexed _auctionId,
        uint256 indexed _tokenId,
        address indexed _seller,
        address _winner,
        uint256 _finalPrice
    );

    event AddAuctionWhiteList(
        uint256 indexed _auctionId,
        uint256 indexed _tokenId,
        address indexed _candidate
    );

    event RemoveAuctionWhiteList(
        uint256 indexed _auctionId,
        uint256 indexed _tokenId,
        address indexed _candidate
    );

    event Transfer(address indexed _from, address indexed _to, uint256 indexed _tokenId);

    event Approval(address indexed _owner, address indexed _approved, uint256 indexed _tokenId);

    event ApprovalForAll(address indexed _owner, address indexed _operator, bool _approved);

    event NewUpgradeApply(
        uint256 indexed _tokenId,
        address indexed _applier,
        uint8 _level,
        uint64 _applyTime,
        uint64 _applyBlockno
    );

    event CancelUpgrade(uint256 indexed _tokenId, address indexed _owner);

    event LevelChanged(
        uint256 indexed _tokenId,
        address indexed _owner,
        uint8 _fromLevel,
        uint8 _toLevel
    );

    event AuctionCancelled(uint256 indexed _auctionId, uint256 indexed _tokenId);

    event ProtocolUpgrade(address _saleAuction);

    event OperatorUpdated(address _op, bool _enabled);

    event BlackListUpdated(address _person, bool _op);

    event Pause();

    event Unpause();

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ------------ Functions ------------ //

    function removeAuctionWhiteList(uint256 _tokenId, address _address) external;

    function supportsInterface(bytes4 _interfaceId) external view returns (bool);

    function sendBonusTo(address _to, uint256 _amount) external;

    function name() external view returns (string memory);

    function isNormalToken(address _target) external view returns (bool);

    function getApproved(uint256 _tokenId) external view returns (address);

    function approve(address _to, uint256 _tokenId) external;

    function operators(address) external view returns (bool);

    function totalSupply() external view returns (uint256);

    function isToken(address _target) external view returns (bool);

    function InterfaceId_ERC165() external view returns (bytes4);

    function setTokenMetadataBaseURI(string memory _newBaseURI) external;

    function transferFrom(address _from, address _to, uint256 _tokenId) external;

    function getTokenParams(uint8 _level) external view returns (uint256, uint64, uint64, uint64);

    function auctionCount() external view returns (uint256);

    function setLeadTime(uint64 _leadtime) external;

    function createDirectionalSaleAuction(
        uint256 _tokenId,
        uint128 _price,
        uint64 _duration,
        address _toAddress
    ) external;

    function unpause() external returns (bool);

    function addToBlackList(address _badGuy) external;

    function bid(uint256 _tokenId) external payable;

    function blackList(address) external view returns (bool);

    function removeFromBlackList(address _innocent) external;

    function canTransfer(uint256 _tokenId) external view returns (bool);

    function paused() external view returns (bool);

    function upgradeTo(uint256 _tokenId, uint8 _toLvl) external;

    function ownerOf(uint256 _tokenId) external view returns (address);

    function transferCooldown() external view returns (uint64);

    function setSaleAuctionAddress(address _address) external;

    function balanceOf(address _owner) external view returns (uint256);

    function applyUpgrade(uint8 _toLvl) external;

    function addToken(
        address _addr,
        uint8 _lvl,
        bool _onUpgrade,
        uint64 _applyUpgradeTime,
        uint64 _applyUpgradeBlockno
    ) external;

    function pause() external returns (bool);

    function leadTime() external view returns (uint64);

    function owner() external view returns (address);

    function symbol() external view returns (string memory);

    function cancelAuction(uint256 _tokenId) external;

    function addOperator(address _operator) external;

    function getMetadata(
        uint256 _tokenId
    ) external view returns (address, uint8, bool, bool, uint64, uint64, uint64);

    function transfer(address _to, uint256 _tokenId) external;

    function removeOperator(address _operator) external;

    function downgradeTo(uint256 _tokenId, uint8 _toLvl) external;

    function cancelUpgrade(uint256 _tokenId) external;

    function setTransferCooldown(uint64 _cooldown) external;

    function createSaleAuction(
        uint256 _tokenId,
        uint128 _startingPrice,
        uint128 _endingPrice,
        uint64 _duration
    ) external;

    function idToOwner(uint256) external view returns (address);

    function tokenURI(uint256 _tokenId) external view returns (string memory);

    function addAuctionWhiteList(uint256 _tokenId, address _address) external;

    function xTokenCount() external view returns (uint64);

    function saleAuction() external view returns (address);

    function ownerToId(address) external view returns (uint256);

    function transferOwnership(address newOwner) external;

    function normalTokenCount() external view returns (uint64);

    function isX(address _target) external view returns (bool);
}

